// expectations at test cleanup. Pass nil for a pure stub.
func NewServiceStub(tb testing.TB, opts ...ServiceStubOption) *ServiceStub {
	s := &ServiceStub{
		OnClose:    &ServiceCloseStub{MethodStub: stub.NewMethodStub[ServiceCloseCall](tb, "Service.Close")},
		OnCount:    &ServiceCountStub{MethodStub: stub.NewMethodStub[ServiceCountCall](tb, "Service.Count")},
		OnDelete:   &ServiceDeleteStub{MethodStub: stub.NewMethodStub[ServiceDeleteCall](tb, "Service.Delete")},
		OnDescribe: &ServiceDescribeStub{MethodStub: stub.NewMethodStub[ServiceDescribeCall](tb, "Service.Describe")},
		OnErr:      &ServiceErrStub{MethodStub: stub.NewMethodStub[ServiceErrCall](tb, "Service.Err")},
		OnGet:      &ServiceGetStub{MethodStub: stub.NewMethodStub[ServiceGetCall](tb, "Service.Get")},
		OnInspect:  &ServiceInspectStub{MethodStub: stub.NewMethodStub[ServiceInspectCall](tb, "Service.Inspect")},
		OnIsEmpty:  &ServiceIsEmptyStub{MethodStub: stub.NewMethodStub[ServiceIsEmptyCall](tb, "Service.IsEmpty")},
		OnList:     &ServiceListStub{MethodStub: stub.NewMethodStub[ServiceListCall](tb, "Service.List")},
		OnLoad:     &ServiceLoadStub{MethodStub: stub.NewMethodStub[ServiceLoadCall](tb, "Service.Load")},
		OnMerge:    &ServiceMergeStub{MethodStub: stub.NewMethodStub[ServiceMergeCall](tb, "Service.Merge")},
		OnPut:      &ServicePutStub{MethodStub: stub.NewMethodStub[ServicePutCall](tb, "Service.Put")},
		OnTouch:    &ServiceTouchStub{MethodStub: stub.NewMethodStub[ServiceTouchCall](tb, "Service.Touch")},
	}
	for _, opt := range opts {
		opt(s)
	}
	if s.strict {
		s.OnClose.Strict()
		s.OnCount.Strict()
		s.OnDelete.Strict()
		s.OnDescribe.Strict()
		s.OnErr.Strict()
		s.OnGet.Strict()
		s.OnInspect.Strict()
		s.OnIsEmpty.Strict()
		s.OnList.Strict()
		s.OnLoad.Strict()
		s.OnMerge.Strict()
		s.OnPut.Strict()
		s.OnTouch.Strict()
	}
	if tb != nil {
		if _, isFuzz := tb.(*testing.F); !isFuzz {
			tb.Cleanup(func() {
				s.OnClose.Verify()
				s.OnCount.Verify()
				s.OnDelete.Verify()
				s.OnDescribe.Verify()
				s.OnErr.Verify()
				s.OnGet.Verify()
				s.OnInspect.Verify()
				s.OnIsEmpty.Verify()
				s.OnList.Verify()
				s.OnLoad.Verify()
				s.OnMerge.Verify()
				s.OnPut.Verify()
				s.OnTouch.Verify()
			})
		}
	}
	return s
}

// ResetCalls clears recorded calls, fault counters, and call-count expectations.
// Func, Returns, and Faults configuration is preserved.
func (s *ServiceStub) ResetCalls() {
	s.OnClose.Reset()
	s.OnCount.Reset()
	s.OnDelete.Reset()
	s.OnDescribe.Reset()
	s.OnErr.Reset()
	s.OnGet.Reset()
	s.OnInspect.Reset()
	s.OnIsEmpty.Reset()
	s.OnList.Reset()
	s.OnLoad.Reset()
	s.OnMerge.Reset()
	s.OnPut.Reset()
	s.OnTouch.Reset()
}

